        <div class="controls">
          <button id="restartBtn">Restart puzzle</button>
          <button id="newBtn" class="secondary">New shuffle</button>
        </div>
        <div id="message" class="message"></div>
      </div>
      <div class="panel stats">
        <h2 style="margin-top:0;">Status</h2>
        <div>Timer: <strong id="timer">0s</strong></div>
        <div>Moves: <strong id="moves">0</strong></div>
        <div>Best completion history:</div>
        <ul id="history"></ul>
        <div class="small" style="margin-top:10px;">Progress is saved locally in your browser and resumes automatically.</div>
      </div>
    </div>
  </div>
  <script>
    const SIZE = 4;
    const STORAGE_KEY = 'qheadache-state-v1';
    const HISTORY_KEY = 'qheadache-history-v1';
    const SOLVED = Array.from({length: SIZE * SIZE - 1}, (_, i) => i + 1).concat(0);

    const boardEl = document.getElementById('board');
    const timerEl = document.getElementById('timer');
    const movesEl = document.getElementById('moves');
    const historyEl = document.getElementById('history');
    const messageEl = document.getElementById('message');
    const restartBtn = document.getElementById('restartBtn');
    const newBtn = document.getElementById('newBtn');

    let state = { board: SOLVED.slice(), moves: 0, startedAt: Date.now(), elapsedBefore: 0, completed: false, originalBoard: SOLVED.slice() };
    let timerHandle = null;

    function isSolved(board) { return board.every((v, i) => v === SOLVED[i]); }
    function saveState() { localStorage.setItem(STORAGE_KEY, JSON.stringify(state)); }
    function saveHistory(record) {
      const history = JSON.parse(localStorage.getItem(HISTORY_KEY) || '[]');
      history.unshift(record);
      localStorage.setItem(HISTORY_KEY, JSON.stringify(history.slice(0, 10)));
      renderHistory();
    }
    function loadHistory() {
      renderHistory();
    }
    function renderHistory() {
      const history = JSON.parse(localStorage.getItem(HISTORY_KEY) || '[]');
      historyEl.innerHTML = history.length ? history.map(h => `<li>${h.time}s, ${h.moves} moves, score ${h.score}</li>`).join('') : '<li>No completed puzzles yet.</li>';
    }
    function currentElapsed() {
      return state.elapsedBefore + Math.floor((Date.now() - state.startedAt) / 1000);
    }
    function updateStats() {
      timerEl.textContent = `${currentElapsed()}s`;
      movesEl.textContent = state.moves;
    }
    function showMessage(text, kind='') {
      messageEl.textContent = text;
      messageEl.className = `message ${kind}`;
    }
    function renderBoard() {
      boardEl.innerHTML = '';
      state.board.forEach((v, idx) => {
        const cell = document.createElement('div');
        cell.className = 'cell ' + (v === 0 ? 'empty' : 'tile');
        cell.setAttribute('role', 'gridcell');
        cell.dataset.idx = idx;
        cell.textContent = v === 0 ? '' : v;
        if (v !== 0) cell.addEventListener('click', () => tryMove(idx));
        cell.addEventListener('touchstart', () => tryMove(idx), {passive:true});
        boardEl.appendChild(cell);
      });
      boardEl.classList.toggle('win', state.completed);
    }
    function adjacent(a, b) {
      const ar = Math.floor(a / SIZE), ac = a % SIZE, br = Math.floor(b / SIZE), bc = b % SIZE;
      return Math.abs(ar - br) + Math.abs(ac - bc) === 1;
    }
    function tryMove(idx) {
      if (state.completed) return;
      const emptyIdx = state.board.indexOf(0);
      if (!adjacent(idx, emptyIdx)) {
        const emptyCell = boardEl.querySelector(`[data-idx="${emptyIdx}"]`);
        emptyCell.classList.add('flash');
        setTimeout(() => emptyCell.classList.remove('flash'), 220);
        showMessage('That move is not allowed. Try a tile next to the blank.', 'bad');
        return;
      }
      [state.board[idx], state.board[emptyIdx]] = [state.board[emptyIdx], state.board[idx]];
      state.moves += 1;
      state.elapsedBefore = currentElapsed();
      state.startedAt = Date.now();
      if (isSolved(state.board)) completePuzzle();
      else showMessage('');
      sync();
    }
    function completePuzzle() {
      state.completed = true;
      const time = currentElapsed();
      const score = Math.max(0, 10000 - time * 10 - state.moves * 25);
      showMessage(`Puzzle completed! Time: ${time}s, Moves: ${state.moves}`, 'good');
      saveHistory({ time, moves: state.moves, score });
      saveState();
    }
    function sync() {
      renderBoard();
      updateStats();
      saveState();
    }
    function resetTo(board) {
      state.board = board.slice();
      state.originalBoard = board.slice();
      state.moves = 0;
      state.completed = false;
      state.elapsedBefore = 0;
      state.startedAt = Date.now();
      showMessage('');
      sync();
    }
    function shuffleBoard() {
      let board = SOLVED.slice();
      do {
        for (let i = board.length - 1; i > 0; i--) {
          const j = Math.floor(Math.random() * (i + 1));
          [board[i], board[j]] = [board[j], board[i]];
        }
      } while (isSolved(board) || !isSolvable(board));
      resetTo(board);
    }
    function isSolvable(board) {
      const arr = board.filter(v => v !== 0);
      let inversions = 0;
      for (let i = 0; i < arr.length; i++) for (let j = i + 1; j < arr.length; j++) if (arr[i] > arr[j]) inversions++;
      const emptyRowFromBottom = SIZE - Math.floor(board.indexOf(0) / SIZE);
      return SIZE % 2 ? inversions % 2 === 0 : (emptyRowFromBottom % 2 === 0) !== (inversions % 2 === 0);
    }
    function loadState() {
      const saved = JSON.parse(localStorage.getItem(STORAGE_KEY) || 'null');
      if (saved && Array.isArray(saved.board) && saved.board.length === SIZE * SIZE) {
        state = saved;
        if (typeof state.elapsedBefore !== 'number') state.elapsedBefore = 0;
        if (!Array.isArray(state.originalBoard)) state.originalBoard = SOLVED.slice();
        showMessage(state.completed ? 'Completed puzzle loaded.' : 'Resumed saved puzzle.', state.completed ? 'good' : '');
      }
    }
    restartBtn.addEventListener('click', () => resetTo(state.originalBoard || SOLVED.slice()));
    newBtn.addEventListener('click', shuffleBoard);

    loadHistory();
    loadState();
    if (!state.board) shuffleBoard();
    renderBoard();
    updateStats();
    if (!state.completed) {
      timerHandle = setInterval(() => updateStats(), 250);
    }
    if (!localStorage.getItem(STORAGE_KEY)) shuffleBoard();
    else sync();
    setInterval(() => { if (!state.completed) updateStats(); }, 1000);
  </script>
</body>
</html>
EOF

